INSERT INTO grammar.content_catalog_topics(version,slug,catalog_hash,payload)
SELECT 'core-2026-09-v4','sentence-structure','87b630c771d79eac83e3be02f06e226cf9455e201ca4d4e9ebd574542396373d',payload || '{"slug":"sentence-structure","title":"Sentence structure and word classes","level":"A1","order":1,"summary":"Start with the building blocks: subjects, verbs, objects, complements and complete clauses.","guidance":"Read the form and meaning together. Study the contrasts, then explain a worked example in your own words before starting a fresh practice session.","learningGoals":["Find the subject and the verb","Objects and complements","Word class depends on its job","A complete written sentence"],"rules":[{"title":"Find the subject and the verb","explanation":"A clause normally contains a **subject** and a **verb phrase**. The subject tells us who or what the clause is about. The verb expresses an action, event or state. In a simple statement, the subject usually comes before the verb. A subject can contain several words.","pattern":"**The new guide** **explains** the route.","commonMistakes":["The first noun you see is not always the subject: in On Monday, the guide arrives, Monday belongs to a time phrase."],"examples":["In “The assistant prepares the visitor guide carefully”, which words are the subject? → **The assistant**","In “The assistant restores the old portrait carefully”, which words are the subject? → **The assistant**"],"skill":"form"},{"title":"Objects and complements","explanation":"A transitive verb can take an **object**, the person or thing affected or involved. After a linking verb such as be or seem, a **complement** describes or identifies the subject instead. Compare She paints the door with The door is blue. Blue describes the door; it is not a thing receiving an action.","pattern":"She opens **the door**. / The door is **heavy**.","commonMistakes":["Some verbs need no object: the baby sleeps. Do not force every sentence into subject–verb–object."],"examples":["In “The assistant prepares the visitor guide carefully”, which word is the main verb? → **prepares**","In “The assistant restores the old portrait carefully”, which word is the main verb? → **restores**"],"skill":"meaning"},{"title":"Word class depends on its job","explanation":"A noun names something, an adjective describes a noun, and an adverb can modify a verb, adjective or clause. The same spelling may have different jobs: a clean room uses clean as an adjective; clean the room uses it as a verb. Identify the word in its sentence.","pattern":"They **carefully** open the **heavy** door.","commonMistakes":["An -ly ending is only a clue: friendly is usually an adjective, and fast can be an adjective or adverb."],"examples":["In “The assistant prepares the visitor guide”, which phrase is the object? → **the visitor guide**","In “The assistant restores the old portrait”, which phrase is the object? → **the old portrait**"],"skill":"contrast"},{"title":"A complete written sentence","explanation":"A written sentence needs a complete main clause and suitable final punctuation. A dependent clause introduced by because or although usually needs a main clause beside it. Commands often leave the subject you unspoken, so Open the door is complete.","pattern":"**Because it was cold, we closed the window.**","commonMistakes":["Because it was cold alone is a fragment in ordinary formal prose, though fragments have purposeful uses in conversation and creative writing."],"examples":["Complete the main clause after a reason: “Because there is time, **we prepare** the visitor guide.”","Complete the main clause after a reason: “Because there is time, **we restore** the old portrait.”"],"skill":"application"}],"tips":[],"source":"seed","provenance":{"kind":"original-guidance-aligned","referenceIds":["dfe-grammar","bc-verbs-reference"],"version":"core-2026-09-v3","reviewStatus":"automated-checked; educator-review-pending"},"chapter":{"introduction":["Start with the building blocks: subjects, verbs, objects, complements and complete clauses.","The form tells you how to build the sentence; the context tells you why that form is useful. Read each section with both questions in mind. The examples make one contrast at a time, while the practice mixes the skills so that you learn to recognise the pattern yourself."],"rules":[{"title":"Find the subject and the verb","explanation":"A clause normally contains a **subject** and a **verb phrase**. The subject tells us who or what the clause is about. The verb expresses an action, event or state. In a simple statement, the subject usually comes before the verb. A subject can contain several words.","pattern":"**The new guide** **explains** the route.","commonMistakes":["The first noun you see is not always the subject: in On Monday, the guide arrives, Monday belongs to a time phrase."],"examples":["In “The assistant prepares the visitor guide carefully”, which words are the subject? → **The assistant**","In “The assistant restores the old portrait carefully”, which words are the subject? → **The assistant**"],"skill":"form","id":"sentence-structure-foundation-1","domain":"foundations","referenceIds":["dfe-grammar","bc-verbs-reference"],"readingVersion":"core-2026-09-v3"},{"title":"Objects and complements","explanation":"A transitive verb can take an **object**, the person or thing affected or involved. After a linking verb such as be or seem, a **complement** describes or identifies the subject instead. Compare She paints the door with The door is blue. Blue describes the door; it is not a thing receiving an action.","pattern":"She opens **the door**. / The door is **heavy**.","commonMistakes":["Some verbs need no object: the baby sleeps. Do not force every sentence into subject–verb–object."],"examples":["In “The assistant prepares the visitor guide carefully”, which word is the main verb? → **prepares**","In “The assistant restores the old portrait carefully”, which word is the main verb? → **restores**"],"skill":"meaning","id":"sentence-structure-foundation-2","domain":"foundations","referenceIds":["dfe-grammar","bc-verbs-reference"],"readingVersion":"core-2026-09-v3"},{"title":"Word class depends on its job","explanation":"A noun names something, an adjective describes a noun, and an adverb can modify a verb, adjective or clause. The same spelling may have different jobs: a clean room uses clean as an adjective; clean the room uses it as a verb. Identify the word in its sentence.","pattern":"They **carefully** open the **heavy** door.","commonMistakes":["An -ly ending is only a clue: friendly is usually an adjective, and fast can be an adjective or adverb."],"examples":["In “The assistant prepares the visitor guide”, which phrase is the object? → **the visitor guide**","In “The assistant restores the old portrait”, which phrase is the object? → **the old portrait**"],"skill":"contrast","id":"sentence-structure-foundation-3","domain":"foundations","referenceIds":["dfe-grammar","bc-verbs-reference"],"readingVersion":"core-2026-09-v3"},{"title":"A complete written sentence","explanation":"A written sentence needs a complete main clause and suitable final punctuation. A dependent clause introduced by because or although usually needs a main clause beside it. Commands often leave the subject you unspoken, so Open the door is complete.","pattern":"**Because it was cold, we closed the window.**","commonMistakes":["Because it was cold alone is a fragment in ordinary formal prose, though fragments have purposeful uses in conversation and creative writing."],"examples":["Complete the main clause after a reason: “Because there is time, **we prepare** the visitor guide.”","Complete the main clause after a reason: “Because there is time, **we restore** the old portrait.”"],"skill":"application","id":"sentence-structure-foundation-4","domain":"foundations","referenceIds":["dfe-grammar","bc-verbs-reference"],"readingVersion":"core-2026-09-v3"},{"domain":"foundations","id":"form-and-function","title":"Word class is different from sentence function","explanation":"A word class tells you what kind of word something is; a function tells you its job in a particular construction. A noun phrase can be a subject, an object or a complement. The same spelling can belong to different classes. Identify the surrounding pattern instead of assigning one permanent class from the dictionary.","pattern":"**class**: noun phrase · **function**: subject or object","examples":["**The runner** waved. / We greeted **the runner**.","They **work** here. / Their **work** is useful."],"commonMistakes":["A subject is a grammatical role, not necessarily a person performing an action: The window broke."],"referenceIds":["cambridge-comprehensive-scope"],"readingVersion":"core-2026-09-v4"},{"domain":"foundations","id":"phrases-and-heads","title":"Phrases, heads and dependents","explanation":"A phrase is organised around a head: a noun, verb, adjective, adverb or preposition. A phrase can contain only its head, or include modifiers and complements. Phrases can contain other phrases, so length alone does not distinguish a phrase from a clause. Find the central word and then identify the words that depend on it.","pattern":"the **roof** of the old house","examples":["The **roof** of the old house needs repair.","She is **very proud of her team**."],"commonMistakes":["A noun phrase may contain a whole relative clause: the house that we bought. The larger phrase still has house as its head."],"referenceIds":["cambridge-comprehensive-scope"],"readingVersion":"core-2026-09-v4"},{"domain":"foundations","id":"finite-subordinate-clauses","title":"Main, subordinate, finite and non-finite clauses","explanation":"A main clause can usually stand as a sentence. A subordinate clause functions inside another construction. A finite clause has a verb marked for tense or a modal; a non-finite clause uses an infinitive or participle without its own independent tense. Subordinate does not mean unimportant: it describes grammatical dependency.","pattern":"I know **that she left**. / I hope **to leave**.","examples":["**When the bell rang**, we left.","They wanted **to finish before dark**."],"commonMistakes":["A short main clause such as Leave! is an imperative, so not every independent clause has an overt subject and tense-marked verb."],"referenceIds":["cambridge-comprehensive-scope"],"readingVersion":"core-2026-09-v4"},{"domain":"foundations","id":"sentence-architectures","title":"Simple, compound and complex sentences","explanation":"A simple sentence contains one main clause. A compound sentence coordinates main clauses. A complex sentence contains subordination; a compound-complex sentence combines coordination and subordination. Count clauses, not verbs or words: a coordinated verb phrase can share one subject. The labels help you see how information is organised.","pattern":"one main clause · coordinated clauses · embedded clauses","examples":["Mina **opened the door and smiled**.","Mina smiled **because we had arrived**, and Leo waved."],"commonMistakes":["Long does not automatically mean complex, and short does not automatically mean simple: I know you lied contains a subordinate content clause."],"referenceIds":["cambridge-comprehensive-scope"],"readingVersion":"core-2026-09-v4"},{"domain":"clause-patterns","id":"clause-complements","title":"Subjects, objects and subject complements","explanation":"An object is selected by a verb; a subject complement describes or identifies the subject after a linking verb. Compare She met a doctor with She became a doctor. Linking verbs include be, seem, become and remain in relevant uses. A complement can be a noun phrase, adjective phrase or another licensed expression.","pattern":"subject + linking verb + **subject complement**","examples":["The room became **quiet**.","My neighbour is **a doctor**."],"commonMistakes":["A noun after a verb is not automatically an object. A doctor identifies the subject after became; it is not something she acted on."],"referenceIds":["cambridge-comprehensive-scope"],"readingVersion":"core-2026-09-v4"},{"domain":"clause-patterns","id":"transitivity-and-valency","title":"Transitive, intransitive and required complements","explanation":"Different verbs license different patterns, sometimes called valency. Arrive can form a clause without an object; put normally needs both an object and a location. Some verbs switch patterns: she opened the door / the door opened. A complement can be required even when it expresses a place or another circumstance.","pattern":"She **put** the keys **on the shelf**.","examples":["The children **laughed**.","We **discussed the proposal**, but we **talked about it**."],"commonMistakes":["Do not infer the pattern from meaning alone: discuss something and talk about something express similar ideas but use different grammar."],"referenceIds":["cambridge-comprehensive-scope"],"readingVersion":"core-2026-09-v4"},{"domain":"clause-patterns","id":"two-object-patterns","title":"Indirect objects, two objects and to/for phrases","explanation":"Some verbs allow a recipient followed by a thing: give someone something. Many also allow a thing followed by a to-phrase; some benefactive patterns use for. These alternatives depend on the verb and on the length and focus of each phrase. They cannot be applied to every verb of communication or transfer.","pattern":"give **her** a book / give a book **to her**","examples":["I sent **Sam a message**. / I sent a message **to Sam**.","She made **us dinner**. / She made dinner **for us**."],"commonMistakes":["Explain and describe normally use to for the recipient: explain the problem to me, not explain me the problem."],"referenceIds":["cambridge-comprehensive-scope"],"readingVersion":"core-2026-09-v4"},{"domain":"clause-patterns","id":"object-complements","title":"Object complements and resultative patterns","explanation":"An object complement describes or identifies the object. It can name a resulting state, as in paint the door blue, or a judgement, as in consider the plan sensible. Keep the object and its complement distinct: in elected her chair, her is the person and chair is the role.","pattern":"verb + object + **object complement**","examples":["The news made **everyone happy**.","They elected **Nora chair**."],"commonMistakes":["An adjective can describe the resulting object while an adverb describes the action: she wiped the table clean / she wiped the table carefully."],"referenceIds":["cambridge-comprehensive-scope"],"readingVersion":"core-2026-09-v4"},{"domain":"foundations","id":"grammar-meaning-context","title":"Grammatical form, meaning and context","explanation":"Grammar organises possible expressions, but context helps determine their intended meaning. A grammatical sentence can be unlikely or ambiguous. A request can have question form, and a past verb form can express politeness or unreality rather than past time. Separate how a sentence is built from what someone uses it to do.","pattern":"**form** + **context** → intended meaning","examples":["Could you move your bag? is normally a **request**.","I was wondering whether you could help is a **polite current enquiry**."],"commonMistakes":["Unusual wording is not automatically ungrammatical. Judge the specified situation, register and variety rather than treating one preferred expression as the only possible one."],"referenceIds":["cambridge-comprehensive-scope"],"readingVersion":"core-2026-09-v4"}],"recap":["**The new guide** **explains** the route.","She opens **the door**. / The door is **heavy**.","They **carefully** open the **heavy** door.","**Because it was cold, we closed the window.**"],"readingVersion":"core-2026-09-v4"},"stage":"1 · Sentence foundations","prerequisites":[],"readingReferenceIds":["dfe-grammar","bc-verbs-reference","cambridge-comprehensive-scope"]}'::jsonb FROM grammar.content_catalog_topics WHERE version='core-2026-09-v3' AND slug='sentence-structure'
